for number in [-1,1<<100,-(1<<100),2147483648,-2147483648]:
 class Key:
  def __hash__(self):return number
  def __eq__(self,other):return other==number
 key=Key()
 print(hash(key)==hash(number),hash((key,))==hash((number,)),len({key,number}),len({number,key}),{key:7}[number],{number:8}[key])

class Base:
 def __hash__(self):return 17
class Child(Base):
 def __eq__(self,other):return True
print(Child.__hash__ is None)
for operation in [lambda:hash(Child()),lambda:{Child()},lambda:{Child():1},lambda:{(Child(),):1}]:
 try:operation();print('bad')
 except TypeError:print('unhashable')

events=[]
class Slot:
 def __get__(self,instance,owner):
  events.append(instance is not None)
  return lambda:7
class Key:__hash__=Slot()
k=Key();k.__hash__=lambda:9
print(hash(k),events,k.__hash__())

for result in [True,False,-1,'bad',None]:
 class Key:
  def __hash__(self):return result
 try:print(hash(Key()))
 except TypeError:print('invalid')

from functools import lru_cache
for number in [-1,1<<100]:
 class Key:
  def __hash__(self):return number
  def __eq__(self,other):return other==number
 events=[]
 @lru_cache(maxsize=8)
 def cached(value):events.append(1);return len(events)
 print(cached((Key(),)),cached((number,)),len(events))

from dataclasses import dataclass
class Base:
 def __hash__(self):return 17
@dataclass
class Value(Base):
 x:int
print(Value.__hash__ is None)
try:hash(Value(1))
except TypeError:print('unhashable')

from dataclasses import dataclass
@dataclass(frozen=True)
class Value:
 x:int
 def __eq__(self,other):return self.x==other.x
print(hash(Value(1))==hash(Value(1)),len({Value(1),Value(1)}))

from dataclasses import dataclass
